module top_module(
    input clk,               // Added missing clk input
    input [15:0] DUTY_CYCLE,
    input [15:0] PERIOD,
    output reg PWM_OUT
);reg [15:0] counter;
reg [15:0] threshold;

// Update threshold based on DUTY_CYCLE and PERIOD
always @(DUTY_CYCLE or PERIOD) begin
    if (PERIOD > 0) begin
        threshold = (DUTY_CYCLE * PERIOD) / 100;
    end else begin
        threshold = 0;
    end
end

// Main PWM logic
always @(posedge clk) begin
    if (counter == PERIOD - 1) begin
        counter <= 0;
    end else begin
        counter <= counter + 1;
    end

    if (counter < threshold) begin
        PWM_OUT <= 1'b1;
    end else begin
        PWM_OUT <= 1'b0;
    end
end

endmodule

