 always @(posedge clk or negedge rst_n) begin 
  if (!rst_n) begin 
  pwm_reg <= 1'h0; 
  end 
  else if (enable) 
  begin 
  if (count_reg < dutyratio) begin 
  pwm_reg <= 1'h1; 
  end 
  else begin 
  pwm_reg <= 1'h0; 
  end 
  end 
 end 
 assign pha = pwm_reg; 
 assign phb = ~pwm_reg; 
 endmodule

