module top_module(
    output reg [3:0] count,
    output overflow,
    input clk,
    input reset_n
);reg [3:0] next_count;

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        next_count <= 4'b0;
    end else begin
        if (count == 4'hf) begin
            next_count <= 4'b0;
        end else begin
            next_count <= count + 1;
        end
    end
end

assign overflow = (count == 4'hf);

always @(*) begin
    count = next_count;
end

endmodule

