module top_module(
    input clk,
    input reset_n,
    output reg [1:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 2'b10
            q <= 2'b10;
        end else begin
            // Ring counter: Shift left and wrap around
            q <= {q[0], q[1]};
        end
    end

