module top_module(
  input reset,
  input clk_async,
  input clk_sync,
  output reg reset_sync
);reg [1:0] sync_reset;

// IO definitions
// reset: reset signal from the asynchronous domain
// clk_async: clock signal from the asynchronous domain
// clk_sync: clock signal from the synchronous domain
// reset_sync: synchronized reset signal in the synchronous domain

// No parameters needed for this module.

// Synchronize reset signal to the synchronous domain
always @(posedge clk_async) begin
  sync_reset <= {sync_reset[0], reset};
end

// Assert synchronized reset signal in the synchronous domain
always @(posedge clk_sync) begin
  reset_sync <= sync_reset[1];
end

endmodule

