module top_module(
  input wire CLK,
  input wire E,
  input wire [31:0] D,
  output reg [31:0] Q
);parameter N = 1;
  reg [31:0] q [0:N-1];
  integer i;

  always @(posedge CLK) begin
    if (E) begin
      for (i = 0; i < N-1; i = i+1) begin
        q[i+1] <= q[i];
      end
      q[0] <= D;
    end
  end

  assign Q = q[N-1];
endmodule

