description:
Design a 4-bit two's complement converter that calculates the negative representation of a binary input value. The circuit uses flip-flops to sequentially shift and accumulate the bitwise negation of the input. When the most significant bit (MSB) indicates a negative number, it computes the two's complement by inverting the bits and adding one. The output reflects the converted two's complement value based on the clock signal for synchronization.
module top_module(
    in,
    out,
    CLK
);

code:
module top_module(
    in,
    out,
    CLK
);input  [3:0] in;
    output [3:0] out;
    input  CLK;

    wire    [3:0] temp;
    wire    [3:0] not_in;

    // Instantiate D Flip-Flops
    reg [3:0] dff_reg; // Use a register to hold the DFF outputs

    always @(posedge CLK) begin
        dff_reg[0] <= in[0] ^ 1;
        dff_reg[1] <= dff_reg[0];
        dff_reg[2] <= dff_reg[1];
        dff_reg[3] <= dff_reg[2];
    end

    assign not_in = ~in;

    // Logic for two's complement
    assign out = (in[3]) ? not_in + 1 : not_in;

endmodule

