description:
Design a data unpacking module that operates with a variable-length input stream. This module processes an input signal, 'din', and produces an output signal, 'dout', based on a clock signal and control signals for synchronization. It utilizes a shift register to store incoming data and manages the flow of data by counting bits to determine when sufficient data is available to produce output. The module supports signaling for the last piece of data and informs when the processing is complete through a 'done' signal. Additionally, it handles conditions for both normal and last data segments, featuring a mechanism to configure the remaining bits dynamically.
module top_module(
    clk, nrst, start, din, vin, dout, vout, remain, last, done
);

code:
module top_module(
    clk, nrst, start, din, vin, dout, vout, remain, last, done
);parameter BITM = 40;
parameter BITN = 8;
parameter LW = 6;

input clk;
input nrst;
input start;
input [BITM-1:0] din;
input vin;
input [LW-1:0] remain;
input last;

output [BITN-1:0] dout;
output vout;
output done;

reg [BITM+BITN-1:0] sreg;
wire [BITM+BITN-1:0] sreg_next;
reg [LW-1:0] cnt;
wire rd;
wire [BITN-1:0] data;
wire [BITM+BITN-1:0] tmp;
wire [BITM+BITN-1:0] tmp2;
wire [LW-1:0] shift;
reg last_i;
reg last_byte_s0;
wire last_byte;

assign dout = data;
assign vout = rd;

always @(posedge clk or negedge nrst) begin
    if (~nrst) begin
        cnt <= 0;
    end else if (start) begin
        cnt <= 0;
    end else if (vin) begin
        if (~last) begin
            cnt <= cnt + BITM;
        end else begin
            cnt <= cnt + remain;
        end
    end else if (rd) begin
        cnt <= cnt - BITN;
    end
end

assign rd = cnt >= BITN;
assign data = sreg[BITM+BITN-1:BITM];
assign tmp = {{BITM{1'b0}}, din};
assign shift = BITN - cnt;
assign tmp2 = (tmp << shift) | sreg;
assign sreg_next = vin ? tmp2 : rd ? {sreg[BITM-1:0], {BITN{1'b0}}} : sreg;

always @(posedge clk or negedge nrst) begin
    if (~nrst) begin
        sreg <= 0;
    end else if (start) begin
        sreg <= 0;
    end else begin
        sreg <= sreg_next;
    end
end

always @(posedge clk or negedge nrst) begin
    if (~nrst) begin
        last_i <= 1'b0;
    end else if (start) begin
        last_i <= 1'b0;
    end else if (vin & last) begin
        last_i <= 1'b1;
    end
end

assign last_byte = last_i && cnt < BITN;

always @(posedge clk) begin
    last_byte_s0 <= last_byte;
end

assign done = ~last_byte_s0 & last_byte;

endmodule

