module top_module(D,
    wr_clk,
    rd_clk,
    WEA,
    tmp_ram_rd_en,
    SR,
    Q,
    count_d1_reg,
    din);output [7:0] D;
  input wr_clk;
  input rd_clk;
  input [0:0] WEA;
  input tmp_ram_rd_en;
  input [0:0] SR;
  output reg [9:0] Q;
  input [9:0] count_d1_reg;
  input [7:0] din;

  reg [10:0] write_pointer;
  reg [10:0] read_pointer;
  reg [10:0] fifo_depth;
  reg [7:0] memory_array [0:1023];

  assign D = memory_array[read_pointer];
  assign Q = fifo_depth;

  always @(posedge wr_clk) begin
    if (WEA) begin
      memory_array[write_pointer] <= din;
      write_pointer <= write_pointer + 1;
      fifo_depth <= fifo_depth + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en) begin
      read_pointer <= read_pointer + 1;
      fifo_depth <= fifo_depth - 1;
    end
  end

  always @(posedge wr_clk, posedge rd_clk, posedge SR) begin
    if (SR) begin
      write_pointer <= 0;
      read_pointer <= 0;
      fifo_depth <= 0;
    end
    else if (write_pointer == count_d1_reg && fifo_depth != 0) begin
      $display("FIFO Full");
    end
    else if (read_pointer == write_pointer && fifo_depth != 0) begin
      $display("FIFO Empty");
    end
  end
endmodule

