`timescale 1ns/1ps

module binary_down_counter_3bit_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg en;
    reg rst;
    wire [2:0] count;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    binary_down_counter_3bit dut (
        .clk(clk),
        .en(en),
        .rst(rst),
        .count(count)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(posedge clk);
            rst <= 1;
            en <= 0;
            @(posedge clk);
            #1;
            rst <= 0;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Test %03d: Initial Reset to 7", test_num);
            reset_dut();
            @(negedge clk);
            #1;

            check_outputs(3'd7);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Test %03d: Single Decrement (7 to 6)", test_num);
            reset_dut();
            @(posedge clk);
            en <= 1;
            @(posedge clk);
            en <= 0;
            @(negedge clk);
            #1;

            check_outputs(3'd6);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Test %03d: Multiple Decrements (7 down to 3)", test_num);
            reset_dut();
            @(posedge clk);
